/** Isolated controller/storage validation. Actual Laravel HTTP/session/SQL are not emulated as passing. */
namespace {
 class HttpError extends \Exception {public function __construct(public int $status,string $message=''){parent::__construct($message,$status);}}
 function abort($code,$msg=''){throw new HttpError($code,$msg);}function abort_unless($ok,$code,$msg=''){if(!$ok)abort($code,$msg);}function abort_if($bad,$code,$msg=''){if($bad)abort($code,$msg);}
 class Actor {public function __construct(public bool $active=true,public bool $isRoot=false,public array $grants=[]){ }public function root(){return $this->isRoot;}public function globalPermission($key){return $this->grants[$key]??false;}}
 class Results {public static array $checks=[];static function check($name,$ok){self::$checks[]=['name'=>$name,'passed'=>(bool)$ok];echo ($ok?'PASS ':'FAIL ').$name."\n";}static function throws($name,$status,$fn){try{$fn();self::check($name,false);}catch(HttpError $e){self::check($name,$e->status===$status);}catch(\Throwable $e){self::check($name,$status===0&&$e instanceof \InvalidArgumentException);}}}
}
namespace App\Models {
 class Setting {static array $rows=[];public function __construct(public string $id,public array $value,public int $version){}static function find($k){return self::$rows[$k]??null;}static function whereKey($k){return new class($k){function __construct(private $k){}function lockForUpdate(){\Illuminate\Support\Facades\DB::$locked++;return $this;}function first(){return Setting::find($this->k);}};}static function create($v){return self::$rows[$v['id']]=new self($v['id'],$v['value'],$v['version']);}function update($v){$this->value=$v['value'];$this->version=$v['version'];return true;}}
}
namespace Illuminate\Http {class Request {function __construct(private ?\Actor $actor,private array $body=[]){}function user(){return $this->actor;}function validate($rules){return $this->body;}}}
namespace Illuminate\Support\Facades {
 class DB {static int $locked=0,$businessLocks=0;static function transaction($fn,$attempts=1){$s=serialize(\App\Models\Setting::$rows);try{return $fn();}catch(\Throwable $e){\App\Models\Setting::$rows=unserialize($s);throw $e;}}static function table($name){if($name!=='app_locks')throw new \Exception('Unexpected table');return new class{function where($k,$v){if($k!=='id'||$v!=='business')throw new \Exception('Missing business lock');return $this;}function increment($k){DB::$businessLocks++;return 1;}};}}
 class Storage {static string $root;static bool $fail=false;static array $reads=[];static function disk($name){if($name!=='local')throw new \Exception('Unexpected storage disk');return new self;}function exists($p){self::$reads[]=$p;return is_file(self::$root.'/'.$p);}function get($p){return file_get_contents(self::$root.'/'.$p);}function put($p,$bytes){if(self::$fail)return false;$dest=self::$root.'/'.$p;if(!is_dir(dirname($dest)))mkdir(dirname($dest),0700,true);return file_put_contents($dest,$bytes)!==false;}}
}
